"""Write all corrected Monte Carlo engine files to /app/.

Applies five mathematical corrections to the pricing engine:
1. Sobol: Gray-code index uses rightmost_zero_bit(i-1) not (i)
2. Inverse normal: tail formula uses sqrt(-2*log) not sqrt(-log)
3. GBM: drift includes Ito correction (r - 0.5*sigma^2)*dt
4. Asian payoff: average excludes S0 from monitoring prices
5. Antithetic variates: negation (-z) not complement (1-z)
"""
import base64
import pathlib

APP = pathlib.Path("/app")
APP.mkdir(parents=True, exist_ok=True)

# Corrected file contents (base64-encoded to avoid quoting issues)
CORRECTED_FILES = {
    "sobol.py": "",
    "norm_inv.py": "",
    "gbm_paths.py": "",
    "payoffs.py": "",
    "mc_pricer.py": "",
}

# main.py and contracts.json are unchanged from the buggy originals
UNCHANGED_FILES = {
    "main.py": "",
    "contracts.json": "",
}

# Write corrected files
for name, b64 in CORRECTED_FILES.items():
    (APP / name).write_bytes(base64.b64decode(b64))
    print(f"  Fixed: {name}")

# Write unchanged files
for name, b64 in UNCHANGED_FILES.items():
    (APP / name).write_bytes(base64.b64decode(b64))
    print(f"  Wrote: {name}")

print("All 5 bugs fixed, all files written to /app/")
